    langgraph: ["State and routing", "State and routing", "Reusable graph design", "Persistence and memory", "Persistence and memory", "Reliable execution", "Reliable execution", "Testing and deployment"],
    rag: ["Ingestion and parsing", "Ingestion and parsing", "Indexing", "Retrieval", "Retrieval", "Grounded generation", "Evaluation", "Evaluation and operations"],
    mcp: ["Protocol foundations", "Protocol foundations", "Tools and resources", "Tools and resources", "Prompts and client features", "Prompts and client features", "Security", "Testing and operations"],
